          "id": "2f6731171faaf5f7b948ee4b5f5e4daf442d94b6",
          "message": "fuzz: repair the harness (zen_init/clear_registered_traits were removed)\n\nThe nightly fuzz workflow has been failing to build since the standalone-tools\nsplit removed zen_facts.c: the harness called zen_init() (which only seeded the\nRNG) and clear_registered_traits() (no such global registry exists — all parser\nregistries are per-ParserContext). Drop both stale calls; the harness now builds\nand the libFuzzer target runs (verified: 2000 iterations clean).",
